"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"

import { cn } from "@/lib/utils"

/*
 * Chrome Azure Checkbox — a recessed steel channel that fills with the azure
 * alloy when checked, matching the primary button material so filled controls
 * read as one metal.
 */

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Checkbox = React.forwardRef<
  HTMLButtonElement,
  WithClassName<CheckboxPrimitive.Root.Props>
>(({ className, indeterminate, ...props }, ref) => (
  <CheckboxPrimitive.Root
    data-slot="checkbox"
    ref={ref}
    indeterminate={indeterminate}
    className={cn(
      "peer inline-flex items-center justify-center h-4 w-4 shrink-0 rounded-[0.3125rem] border-[0.0938rem] border-white/10 bg-origin-border",
      "bg-input [box-shadow:var(--shadow-inset)]",
      "transition-[background,box-shadow,border-color] duration-fast",
      "hover:border-ring/40",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40",
      "data-disabled:cursor-not-allowed data-disabled:opacity-50",
      // Checked/indeterminate = the primary button material: metal-rim border + azure alloy fill.
      "data-checked:border-transparent data-checked:[background:var(--surface-on)_padding-box,var(--metal-rim)_border-box] data-checked:text-primary-foreground data-checked:[box-shadow:var(--shadow-primary)]",
      "data-indeterminate:border-transparent data-indeterminate:[background:var(--surface-on)_padding-box,var(--metal-rim)_border-box] data-indeterminate:text-primary-foreground data-indeterminate:[box-shadow:var(--shadow-primary)]",
      className
    )}
    {...props}
  >
    <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
      {indeterminate ? (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" className="h-3 w-3">
          <path d="M5 12h14" />
        </svg>
      ) : (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="h-3 w-3">
          <path d="M5 12l5 5L20 7" />
        </svg>
      )}
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
))
Checkbox.displayName = "Checkbox"

export { Checkbox }
